use async_graphql_axum::{GraphQLRequest, GraphQLResponse};
use axum::{extract::State, response::IntoResponse, routing::post, Router};
use url::Url;

use super::DynamicSchema;

/// A running mock GraphQL server backed by a [`DynamicSchema`].
pub struct MockGraphQlServer {
    shutdown: Option<tokio::sync::oneshot::Sender<()>>,
    name: String,
    sdl: String,
    url: Url,
}

impl Drop for MockGraphQlServer {
    fn drop(&mut self) {
        if let Some(shutdown) = self.shutdown.take() {
            shutdown.send(()).ok();
        }
    }
}

#[derive(Clone)]
struct AppState {
    schema: Arc<DynamicSchema>,
}

impl MockGraphQlServer {
    pub(super) async fn new(name: String, schema: DynamicSchema) -> Self {
        let sdl = schema.sdl().to_string();
        let state = AppState {
            schema: Arc::new(schema),
        };

        let app = Router::new()
            .route("/", post(graphql_handler))
            .with_state(state.clone());

        let listener = tokio::net::TcpListener::bind((Ipv4Addr::LOCALHOST, 0)).await.unwrap();
        let listen_address = listener.local_addr().unwrap();

        let (shutdown_sender, shutdown_receiver) = tokio::sync::oneshot::channel::<()>();

        tokio::spawn(async move {
            axum::serve(listener, app)
                .with_graceful_shutdown(async move {
                    shutdown_receiver.await.ok();
                })
                .await
                .unwrap();
        });

        let url = format!("http://{listen_address}").parse().unwrap();

        MockGraphQlServer {
            shutdown: Some(shutdown_sender),
            name,
            sdl,
            url,
        }
    }

    /// The name of the subgraph.
    pub fn name(&self) -> &str {
        &self.name
    }

    /// The SDL of the subgraph.
    pub fn sdl(&self) -> &str {
        &self.sdl
    }

    /// The URL the mock server is listening on.
    pub fn url(&self) -> &Url {
        &self.url
    }
}

async fn graphql_handler(State(state): State<AppState>, req: GraphQLRequest) -> axum::response::Response {
    let req = req.into_inner();
    let response: GraphQLResponse = state.schema.execute(req).await.into();

    response.into_response()
}
